		internal const float FaceLightN = 0.92530f, FaceLightW = 0.92530f, FaceLightE = 1.12398f, ShadowDark = 0.40127f;
		// END GOLDEN

		private static void Assert(bool ok, string msg)
		{
			if (!ok) throw new Exception(msg);
		}

		private static bool Near(float a, float b, float eps = 1e-3f) => Math.Abs(a - b) < eps;

		public static void Run(Action<string, Action> Case)
		{
			Case("PitStepped_curves_match_the_twin", () =>
			{
				Assert(CurveGolden.GetLength(0) == 41, "can-fail: the curve table is filled");
				for (int i = 0; i < CurveGolden.GetLength(0); i++)
				{
					float n = CurveGolden[i, 0];
					Assert(Near(RM_PitReliefMath.StepH(n), CurveGolden[i, 1], 1e-4f) && Near(RM_PitReliefMath.StepW(n), CurveGolden[i, 2], 1e-4f)
						&& Near(RM_PitReliefMath.StepK(n), CurveGolden[i, 3], 1e-4f),
						"can-fail: H/W/K(" + n + ") = " + RM_PitReliefMath.StepH(n) + " " + RM_PitReliefMath.StepW(n) + " " + RM_PitReliefMath.StepK(n)
						+ ", twin " + CurveGolden[i, 1] + " " + CurveGolden[i, 2] + " " + CurveGolden[i, 3]);
				}
			});
			Case("PitStepped_plans_match_the_twin", () =>
			{
				Assert(PlanGolden.GetLength(0) > 30, "can-fail: the plan table is filled");
				for (int i = 0; i < PlanGolden.GetLength(0); i++)
				{
					int d = (int)PlanGolden[i, 0], n = (int)PlanGolden[i, 1], s = (int)PlanGolden[i, 2], w = (int)PlanGolden[i, 3],
						e = (int)PlanGolden[i, 4], nw = (int)PlanGolden[i, 5], ne = (int)PlanGolden[i, 6];
					float lv = PlanGolden[i, 7];
					RM_PitReliefMath.StepPlan p = RM_PitReliefMath.PlanStep(d, n, s, w, e, nw, ne, lv);
					float[] got =
					{
						p.T, p.L, p.R, p.Lt, p.Rt, p.HvL, p.HvR, p.Sl, p.CnwW, p.CnwH, p.CneW, p.CneH,
						p.LipN ? p.LipN0 : -1f, p.LipN ? p.LipN1 : -1f, p.LipW ? p.LipW0 : -1f, p.LipE ? p.LipE0 : -1f,
						p.EdgeN ? 1f : 0f, p.EdgeS ? 1f : 0f, p.EdgeW ? 1f : 0f, p.EdgeE ? 1f : 0f,
					};
					for (int k = 0; k < got.Length; k++)
					{
						Assert(Near(got[k], PlanGolden[i, 8 + k]), "can-fail: plan(" + d + "," + n + "," + s + "," + w + "," + e + "," + nw + "," + ne
							+ ", lv " + lv + ") value " + k + " = " + got[k] + ", twin " + PlanGolden[i, 8 + k]);
					}
				}
			});
			Case("PitStepped_cast_shadow_matches_the_twin", () =>
			{
				Assert(LitGolden.GetLength(0) > 200, "can-fail: the shadow table is filled");
				int[] win = new int[25];
				int shaded = 0, wrong = 0;
				string first = null;
				for (int i = 0; i < LitGolden.GetLength(0); i++)
				{
					for (int k = 0; k < 25; k++)
					{
						win[k] = (int)LitGolden[i, k];
					}
					float lit = RM_PitReliefMath.Lit(win, LitGolden[i, 25], LitGolden[i, 26]);
					if (LitGolden[i, 27] < 0.5f) shaded++;
					if (!Near(lit, LitGolden[i, 27], 0.02f))
					{
						wrong++;
						first = first ?? ("at row " + i + ": " + lit + ", twin " + LitGolden[i, 27]);
					}
				}
				Assert(shaded > 10, "can-fail: the table holds shaded points (" + shaded + ")");
				Assert(wrong == 0, "can-fail: " + wrong + " shadow points differ from the twin, first " + first);
				Assert(Near(RM_PitReliefMath.FaceLight(0), FaceLightN) && Near(RM_PitReliefMath.FaceLight(1), FaceLightW)
					&& Near(RM_PitReliefMath.FaceLight(2), FaceLightE) && Near(RM_PitReliefMath.ShadowDark, ShadowDark),
					"can-fail: the face light and shadow depth match the twin");
			});
			Case("PitStepped_floor_darkens_at_every_depth_and_2m_keeps_its_look", () =>
			{
				Assert(RM_PitReliefMath.StepFloorShade(4) == 0f, "can-fail: the 2 m floor keeps today's look (" + RM_PitReliefMath.StepFloorShade(4) + ")");
				float prev = 2f;
				for (int d = 1; d <= 40; d++)
				{
					float b = RM_PitReliefMath.StepFloorBrightness(d);
					Assert(b < prev, "can-fail: the floor at " + d + " notches (" + b + ") is darker than at " + (d - 1) + " (" + prev + ")");
					float a = RM_PitReliefMath.StepFloorShade(d);
					Assert(a >= 0f && a < 1f, "can-fail: shade alpha in range at " + d);
					prev = b;
				}
				// each level clearly apart: a floor twice as deep is at least 15 % darker, at every depth (his 4 m / 8 m L included)
				for (int d = 1; d <= 20; d++)
				{
					float b1 = RM_PitReliefMath.StepFloorBrightness(d), b2 = RM_PitReliefMath.StepFloorBrightness(2 * d);
					Assert(b2 < 0.85f * b1, "can-fail: the floor at " + (2 * d) + " notches (" + b2 + ") is clearly darker than at " + d + " (" + b1 + ")");
				}
			});
			Case("PitStepped_north_shelf_stays_in_view", () =>
			{
				// his words (2026-11-22): "the lower-right northern inner shelf is incredibly narrow, that's a bit weird and incorrect";
				// his L's 4 m north arm showed 0.26 of a square. A one-square shelf along a north wall keeps 0.4 in view to 8 m.
				for (int n = 1; n <= 16; n++)
				{
					Assert(1f - RM_PitReliefMath.StepH(n) >= 0.4f, "can-fail: a one-square north shelf at " + n + " notches shows "
						+ (1f - RM_PitReliefMath.StepH(n)) + " of a square");
				}
			});
			Case("PitStepped_face_sizes_follow_the_relief_switch", () =>
			{
				bool was = RM_UnderLiquid.Relief;
				try
				{
					RM_UnderLiquid.Relief = true;
					// his L: a 4 m floor north of an 8 m floor shows only the part between them
					Assert(Near(RM_UnderLiquid.NorthFaceAt(16, 8, 0f), RM_PitReliefMath.StepH(16) - RM_PitReliefMath.StepH(8)),
						"can-fail: relief on, a riser shows H(b) - H(a)");
					Assert(RM_UnderLiquid.SideFaceAt(16, 0, 0f) > RM_UnderLiquid.SideFaceAt(8, 0, 0f) + 0.05f,
						"can-fail: relief on, an 8 m side wall is wider than a 4 m one (today both stop at 2.5 m)");
					Assert(Near(RM_UnderLiquid.NorthFaceAt(16, 0, 4f), RM_PitReliefMath.StepH(12)), "can-fail: water hides the face's foot");
					RM_UnderLiquid.Relief = false;
					Assert(Near(RM_UnderLiquid.NorthFaceAt(16, 8, 0f), RM_UnderLiquid.NorthFace(8f)), "can-fail: relief off, today's face by the drop");
					Assert(Near(RM_UnderLiquid.SideFaceAt(16, 0, 0f), RM_UnderLiquid.SideFaceAt(8, 0, 0f)), "can-fail: relief off, today's clamp");
				}
				finally
				{
					RM_UnderLiquid.Relief = was;
				}
			});
		}
	}
}
